<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>2048</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      user-select: none;
    }

    body {
      background-color: #121213;
      color: #f8f9fa;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }

    .container {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 16px;
      width: 360px;
    }

    header {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    h1 {
      font-size: 40px;
      font-weight: 800;
      color: #ffffff;
      letter-spacing: -1px;
    }

    .header-right {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .score-container {
      background: #27272a;
      padding: 6px 14px;
      border-radius: 6px;
      text-align: center;
      min-width: 80px;
    }

    .score-label {
      font-size: 11px;
      text-transform: uppercase;
      font-weight: 700;
      color: #a1a1aa;
    }

    #score {
      font-size: 20px;
      font-weight: 700;
      color: #ffffff;
    }

    #reset {
      background: #3f3f46;
      color: #ffffff;
      border: none;
      padding: 10px 16px;
      font-size: 14px;
      font-weight: 600;
      border-radius: 6px;
      cursor: pointer;
      transition: background 0.15s ease;
    }

    #reset:hover {
      background: #52525b;
    }

    #board {
      width: 360px;
      height: 360px;
      background: #18181b;
      border: 2px solid #27272a;
      border-radius: 8px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      grid-template-rows: repeat(4, 1fr);
      gap: 8px;
      padding: 8px;
    }

    .cell {
      background: #27272a;
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      font-weight: 700;
      color: #f4f4f5;
    }

    .tile-2    { background: #3f3f46; color: #f4f4f5; }
    .tile-4    { background: #52525b; color: #f4f4f5; }
    .tile-8    { background: #b45309; color: #ffffff; }
    .tile-16   { background: #c2410c; color: #ffffff; }
    .tile-32   { background: #b91c1c; color: #ffffff; }
